import json, subprocess, datetime, collections

CUTOFF = "2026-05-30T00:00:00Z"
cutoff_dt = datetime.datetime.fromisoformat(CUTOFF.replace("Z","+00:00"))

query = '''
query($cursor: String) {
  repository(owner: "entireio", name: "cli") {
    pullRequests(first: 50, after: $cursor, orderBy: {field: UPDATED_AT, direction: DESC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        number
        updatedAt
        reviews(first: 100) {
          nodes {
            author { login }
            submittedAt
            state
          }
        }
      }
    }
  }
}
'''

cursor = None
# reviewer -> set of PR numbers reviewed in window
pr_reviews = collections.defaultdict(set)
# reviewer -> count of review events in window
event_counts = collections.defaultdict(int)
# reviewer -> states breakdown
state_counts = collections.defaultdict(lambda: collections.Counter())

stop = False
pages = 0
while not stop:
    args = ["gh","api","graphql","-f","query="+query]
    if cursor:
        args += ["-f","cursor="+cursor]
    out = subprocess.run(args, capture_output=True, text=True)
    if out.returncode != 0:
        print("ERR", out.stderr); break
    data = json.loads(out.stdout)["data"]["repository"]["pullRequests"]
    pages += 1
    all_old = True
    for pr in data["nodes"]:
        upd = datetime.datetime.fromisoformat(pr["updatedAt"].replace("Z","+00:00"))
        if upd >= cutoff_dt:
            all_old = False
        for rv in pr["reviews"]["nodes"]:
            sa = rv.get("submittedAt")
            if not sa: continue
            sdt = datetime.datetime.fromisoformat(sa.replace("Z","+00:00"))
            if sdt < cutoff_dt: continue
            login = (rv["author"] or {}).get("login","(unknown)")
            pr_reviews[login].add(pr["number"])
            event_counts[login]+=1
            state_counts[login][rv["state"]]+=1
    # since ordered by updatedAt desc, once a whole page is older than cutoff, stop
    if data["pageInfo"]["hasNextPage"] and not all_old:
        cursor = data["pageInfo"]["endCursor"]
    else:
        stop = True

print(f"Pages fetched: {pages}")
print(f"Cutoff: {CUTOFF}\n")
print(f"{'Reviewer':<22}{'PRs reviewed':>14}{'Review events':>16}")
print("-"*52)
for login,prs in sorted(pr_reviews.items(), key=lambda x:-len(x[1])):
    print(f"{login:<22}{len(prs):>14}{event_counts[login]:>16}")

total_prs = set()
for s in pr_reviews.values(): total_prs|=s
print("-"*52)
print(f"{'Distinct PRs reviewed':<22}{len(total_prs):>14}{sum(event_counts.values()):>16}")
EOF
