import json, subprocess, datetime, collections

CUTOFF = "2026-05-30T00:00:00Z"
cutoff_dt = datetime.datetime.fromisoformat(CUTOFF.replace("Z","+00:00"))

query = '''
query($cursor: String) {
  repository(owner: "entireio", name: "cli") {
    pullRequests(first: 50, after: $cursor, orderBy: {field: UPDATED_AT, direction: DESC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        number
        updatedAt
        author { login }
        reviews(first: 100) {
          nodes { author { login } submittedAt }
        }
      }
    }
  }
}
'''

cursor=None; stop=False
pr_reviews = collections.defaultdict(set)            # reviewer -> set(PR)
event_counts = collections.defaultdict(int)          # reviewer -> events
# reviewer -> author -> set(PR)
by_author = collections.defaultdict(lambda: collections.defaultdict(set))

while not stop:
    args=["gh","api","graphql","-f","query="+query]
    if cursor: args+=["-f","cursor="+cursor]
    out=subprocess.run(args,capture_output=True,text=True)
    if out.returncode!=0: print("ERR",out.stderr); break
    data=json.loads(out.stdout)["data"]["repository"]["pullRequests"]
    all_old=True
    for pr in data["nodes"]:
        upd=datetime.datetime.fromisoformat(pr["updatedAt"].replace("Z","+00:00"))
        if upd>=cutoff_dt: all_old=False
        author=(pr["author"] or {}).get("login","(unknown)")
        for rv in pr["reviews"]["nodes"]:
            sa=rv.get("submittedAt")
            if not sa: continue
            sdt=datetime.datetime.fromisoformat(sa.replace("Z","+00:00"))
            if sdt<cutoff_dt: continue
            login=(rv["author"] or {}).get("login","(unknown)")
            if login==author: continue  # ignore self-reviews
            pr_reviews[login].add(pr["number"])
            event_counts[login]+=1
            by_author[login][author].add(pr["number"])
    if data["pageInfo"]["hasNextPage"] and not all_old:
        cursor=data["pageInfo"]["endCursor"]
    else: stop=True

print(f"{'Reviewer':<24}{'PRs':>5}{'Events':>8}   Top authors reviewed (PRs)")
print("-"*100)
for login,prs in sorted(pr_reviews.items(), key=lambda x:-len(x[1])):
    tops=sorted(by_author[login].items(), key=lambda x:-len(x[1]))[:3]
    s="  ".join(f"{a} ({len(p)})" for a,p in tops)
    print(f"{login:<24}{len(prs):>5}{event_counts[login]:>8}   {s}")
EOF
